    stopStudioPreflightBackgroundPolling();
    if (uiSession) {
      await uiSession.close().catch(() => undefined);
    }
    throw error;
  }
  const activeSession = uiSession;
  if (!activeSession) {
    stopStudioPreflightBackgroundPolling();
    throw new Error('Studio UI session did not initialize.');
  }

