  const shutdown = async () => {
    if (shuttingDown) {
      return;
    }
    shuttingDown = true;
    stopStudioPreflightBackgroundPolling();
    await activeSession.close().catch(() => undefined);
    await clearRuntimeMetadataIfOwned(repoRoot, process.pid);
  };
